import{_ as e}from"./chunks/硬件架构.CBEg5olg.js";import{c as a,Q as r,j as d,m as o}from"./chunks/framework.DOi4mjdC.js";const B=JSON.parse('{"title":"2201到3510架构变更","description":"","frontmatter":{},"headers":[{"level":1,"title":"2201到3510架构变更","slug":"2201到3510架构变更"}],"relativePath":"guide/跨代迁移兼容性指南/3510架构迁移指导/2201到3510架构变更.md","filePath":"guide/跨代迁移兼容性指南/3510架构迁移指导/2201到3510架构变更.md"}'),n={name:"guide/跨代迁移兼容性指南/3510架构迁移指导/2201到3510架构变更.md"};function i(l,t,s,p,c,f){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="_2201到3510架构变更" tabindex="-1">2201到3510架构变更 <a class="header-anchor" href="#_2201到3510架构变更" aria-label="Permalink to &quot;2201到3510架构变更&quot;">​</a></h1><p><a href="./../../编程指南/语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">NPU架构版本3510</a>的架构图如<a href="#fig1097417534526">图1</a>所示，总体来看，3510架构新增了以下特性：</p><ul><li>新增多条数据通路。</li><li>AI Core核数增加。</li><li>UB容量提升。</li><li>新增SSBuffer核内存储单元，支持AIC核和AIV核通过Scalar访问。</li><li>SIMD编程基础上，支持SIMT编程、SIMD与SIMT混合编程。</li><li>AIV核采用Regbase架构，与<a href="./../../编程指南/语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">NPU架构版本2201</a>的Membase架构相比，可以直接对芯片的Vector寄存器Register进行操作，实现更大的灵活性和更好的性能。</li></ul><p><strong>图 1</strong> 3510架构图<br><img src="'+e+'" alt="" title="硬件架构"></p><p>具体来说，3510架构的主要变更如下各表所示。除此之外，3510架构还扩展了支持的数据类型，具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E5%86%85%E7%BD%AE%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B.md" target="_blank" rel="noreferrer">数据类型介绍</a>。</p><ul><li><p>搬运单元</p><p><strong>表 1</strong> 搬运单元变更</p><table tabindex="0"><thead><tr><th>3510变更</th><th>产生的影响</th><th>影响的API接口</th></tr></thead><tbody><tr><td>删除L1 Buffer到GM的数据通路。</td><td>现有接口不支持从L1 Buffer直接搬运数据到GM。开发者需要在L1 Buffer分配一块空间存放单位矩阵，利用MMAD矩阵乘法计算输出到L0C Buffer，从L0C Buffer通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Fixpipe.md" target="_blank" rel="noreferrer">Fixpipe</a>将数据搬运到GM。</td><td>DataCopy/DumpTensor</td></tr><tr><td>删除GM到L0A Buffer、L0B Buffer的数据通路。</td><td>原GM到L0A Buffer和L0B Buffer的数据搬运需要拆分为两步，即从GM到L1 Buffer的数据搬运和从L1 Buffer到L0A Buffer、L0B Buffer的数据搬运。</td><td>LoadData</td></tr><tr><td>新增UB到L1 Buffer的数据通路。</td><td>支持将数据直接从UB搬运到L1 Buffer，而无需先从UB搬运到GM，再从GM搬运到L1 Buffer，使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E5%9F%BA%E7%A1%80%E6%95%B0%E6%8D%AE%E6%90%AC%E8%BF%90.md" target="_blank" rel="noreferrer">基础数据搬运</a>。</td><td>DataCopy</td></tr><tr><td>新增ND-DMA指令。</td><td>扩展DataCopy数据搬运接口的能力，相比基础数据搬运接口，可更加自由地配置搬入数据的维度信息及Stride，使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E5%A4%9A%E7%BB%B4%E6%95%B0%E6%8D%AE%E6%90%AC%E8%BF%90%EF%BC%88ISASI%EF%BC%89.md" target="_blank" rel="noreferrer">多维数据搬运（ISASI）</a>。</td><td>DataCopy</td></tr><tr><td>新增L0C Buffer到UB的单向数据通路。</td><td>支持将数据直接从L0C Buffer搬运到UB，而无需先从L0C Buffer搬运到GM，再从GM搬运到UB，使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Fixpipe.md" target="_blank" rel="noreferrer">Fixpipe</a>。</td><td>Fixpipe</td></tr><tr><td>扩展LoadData搬运指令。</td><td>新增支持MicroScaling（MX）场景的数据搬运，使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/LoadData.md" target="_blank" rel="noreferrer">LoadData</a>。</td><td>LoadData</td></tr><tr><td>新增DN分型、L1Buffer-&gt;L0A Buffer不再支持transpose。</td><td>使用新特性具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/LoadDataWithTranspose.md" target="_blank" rel="noreferrer">LoadDataWithTranspose</a>。</td><td>LoadDataWithTranspose</td></tr><tr><td>Fixpipe新增NZ2DN随路转换（实现NZ到DN数据格式的随路变换）。</td><td>使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Fixpipe.md" target="_blank" rel="noreferrer">Fixpipe</a>。</td><td>Fixpipe</td></tr><tr><td>DataCopy搬运维度增强。</td><td>DataCopy支持L1 Buffer与GM之间，GM与UB之间通路的loop模式搬运，使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetLoopModePara.md" target="_blank" rel="noreferrer">SetLoopModePara</a>。</td><td>DataCopy</td></tr><tr><td>3510架构版本中删除了与L0A Buffer和L0B Buffer初始化相关的硬件指令。</td><td>使用基础API <a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/InitConstValue.md" target="_blank" rel="noreferrer">InitConstValue</a>将特定存储位置的LocalTensor初始化为某一具体数值，不支持直接初始化L0A Buffer、L0B Buffer上的LocalTensor。</td><td>InitConstValue</td></tr></tbody></table></li><li><p>计算单元</p><p><strong>表 2</strong> 计算单元变更</p><table tabindex="0"><thead><tr><th>3510变更</th><th>产生的影响</th><th>影响的API接口</th></tr></thead><tbody><tr><td>Cube计算单元不支持s4类型。</td><td>对于int4b_t数据类型的矩阵乘计算，开发者需要先将int4b_t的数据Cast转换为int8_t类型，再进行Cube计算。</td><td>Mmad</td></tr><tr><td>Cube计算单元不支持L0A上ZZ到ZN的分形变化。</td><td>L0A切分场景下，矩阵乘需要重新计算左矩阵的L0A地址。</td><td>LoadData/LoadDataWithTranspose</td></tr><tr><td>Vector Core Membase架构切换到Regbase架构。</td><td>基础API部分场景性能降低。</td><td>基础API高维切分模式</td></tr><tr><td>硬件不支持Subnormal功能，当前使用软仿实现的Subnormal功能。</td><td>开发者需要通过设置config模板参数来配置Subnormal计算模式，具体请参考<a href="./2201迁移3510指导/基础API迁移指导.html#section7364115741514">矢量计算</a>。</td><td>Ln/Sqrt/Rsqrt/Div/Reciprocal/Exp</td></tr><tr><td>不支持4:2稀疏矩阵的计算。</td><td>开发者需要利用Vector Core的能力，进行矩阵稠密转稀疏操作。</td><td>LoadDataWithSparse/MmadWithSparse</td></tr></tbody></table></li><li><p>存储单元</p><p><strong>表 3</strong> 存储单元变更</p><table tabindex="0"><thead><tr><th>3510变更</th><th>产生的影响</th><th>影响的API接口</th></tr></thead><tbody><tr><td>删除L1 Buffer空间的边界值设定。</td><td>3510架构硬件删除了L1 Buffer的边界值设定相关寄存器，不再支持SetLoadDataBoundary接口，具体请参考<a href="./2201迁移3510指导/基础API迁移指导.html">基础API迁移指导</a>。</td><td>SetLoadDataBoundary</td></tr><tr><td>UB结构变化。2201架构的UB结构和3510架构的UB结构对比请参考<a href="./../../算子实践参考/SIMD算子性能优化/内存访问/避免UB的bank冲突/概述.html">bank结构对比</a>。</td><td>2201架构上UB分为16个bank group，每个bank group包含3个bank，每个bank大小为4KB。3510架构上UB分为8个bank group，每个bank group包含2个bank，每个bank大小为16KB。若发生UB冲突，开发者可参考<a href="./../../算子实践参考/SIMD算子性能优化/内存访问/避免UB的bank冲突/概述.html">避免UB的bank冲突</a>解决UB冲突。</td><td>/</td></tr></tbody></table></li><li><p>同步</p><p><strong>表 4</strong> 同步变更</p><table tabindex="0"><thead><tr><th>3510变更</th><th>产生的影响</th><th>影响的API接口</th></tr></thead><tbody><tr><td>新增Mutex能力。</td><td>Mutex用于核内异步流水指令之间的同步处理，其功能类似于传统CPU中的锁机制。通过锁定指定流水再释放流水来完成流水间的同步依赖，使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Mutex%EF%BC%88ISASI%EF%BC%89.md" target="_blank" rel="noreferrer">Mutex（ISASI）</a>。</td><td>Mutex</td></tr><tr><td>新增核间同步控制模式。</td><td>对于AI Core内部的同步控制，AIV0与AIV1可单独触发AIC等待，使用方式具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/CrossCoreSetFlag(ISASI).md" target="_blank" rel="noreferrer">CrossCoreSetFlag(ISASI)</a>。</td><td>CrossCoreSetFlag/CrossCoreWaitFlag</td></tr></tbody></table></li><li><p>其它</p><p><strong>表 5</strong> 其它变更</p><table tabindex="0"><thead><tr><th>3510变更</th><th>产生的影响</th><th>影响的API接口</th></tr></thead><tbody><tr><td>删除AIPP硬件级指令，采用软仿实现AIPP功能。</td><td>AIPP接口性能可能有所下降。</td><td>SetAippFunctions/LoadImageToLocal</td></tr><tr><td>由于3510架构版本中相关寄存器的删除，UB异常调试接口也被移除。</td><td>调测接口对功能无影响。</td><td>CheckLocalMemoryIA</td></tr></tbody></table></li></ul>',6)])])}const u=a(n,[["render",i]]);export{B as __pageData,u as default};
